const total = ctx.words.length;
const latest = Math.max(ctx.duration - 0.6, 0);
const cue = (fraction) => Math.min(ctx.at(Math.min(Math.round(fraction * (total - 1)), total - 1)), latest);
const wordsFrom = (start, count) => ctx.words.slice(start, start + count).map((word) => word.text).join(" ");
const clean = (text, limit) => text.replace(/[^\p{L}\p{N}]/gu, "").slice(0, limit);
const orbit = document.createElement("div");
orbit.className = "mo-a-orbit";
for (let index = 0; index < 3; index += 1) {
  const pulse = document.createElement("div");
  pulse.className = "mo-a-pulse";
  orbit.append(pulse);
}
const spinner = document.createElement("div");
spinner.className = "mo-a-spinner";
orbit.append(spinner);
const bars = document.createElement("div");
bars.className = "mo-a-bars";
for (let index = 0; index < 5; index += 1) {
  const bar = document.createElement("div");
  bar.className = "mo-a-bar";
  bar.style.animationDelay = "-" + (index * 0.35).toFixed(2) + "s";
  bars.append(bar);
}
const headline = document.createElement("p");
headline.className = "mo-a-headline " + (total > 12 ? "mo-a-small" : "mo-a-large");
headline.textContent = ctx.text;
ctx.root.append(orbit, bars, headline);
ctx.timeline.from(headline, { opacity: 0, y: 36, duration: 0.6, ease: "power3.out" }, cue(0.1));

