.mo-s-{{sceneId}} {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.mo-s-{{sceneId}} .mo-a-orbit {
  position: relative;
  flex: none;
  width: calc(var(--mo-unit) * 20);
  height: calc(var(--mo-unit) * 20);
  margin-bottom: calc(var(--mo-unit) * 3);
}
.mo-s-{{sceneId}} .mo-a-pulse {
  position: absolute;
  inset: 0;
  border: calc(var(--mo-unit) * 0.5) solid var(--mo-accent);
  border-radius: 999px;
  animation: mo-s-{{sceneId}}-pulse 2s ease-out infinite both;
}
.mo-s-{{sceneId}} .mo-a-pulse:nth-child(2) {
  animation-delay: -1.33s;
}
.mo-s-{{sceneId}} .mo-a-pulse:nth-child(3) {
  animation-delay: -0.66s;
}
.mo-s-{{sceneId}} .mo-a-spinner {
  position: absolute;
  inset: 18%;
  border: calc(var(--mo-unit) * 0.6) solid var(--mo-border);
  border-radius: 999px;
  animation: mo-s-{{sceneId}}-spin 3s linear infinite;
}
.mo-s-{{sceneId}} .mo-a-spinner::after {
  content: "";
  position: absolute;
  top: calc(var(--mo-unit) * -1.6);
  left: calc(50% - var(--mo-unit) * 1.6);
  width: calc(var(--mo-unit) * 3.2);
  height: calc(var(--mo-unit) * 3.2);
  border-radius: 999px;
  background: var(--mo-accent);
}
.mo-s-{{sceneId}} .mo-a-bars {
  display: flex;
  align-items: flex-end;
  gap: calc(var(--mo-unit) * 2);
  height: calc(var(--mo-unit) * 9);
  margin-bottom: calc(var(--mo-unit) * 3);
}
.mo-s-{{sceneId}} .mo-a-bar {
  width: calc(var(--mo-unit) * 4);
  height: 100%;
  border-radius: calc(var(--mo-unit) * 1) calc(var(--mo-unit) * 1) 0 0;
  background: var(--mo-accent);
  transform-origin: bottom center;
  animation: mo-s-{{sceneId}}-bar 1.8s ease-in-out infinite alternate;
}
.mo-s-{{sceneId}} .mo-a-headline {
  margin: 0;
  max-width: 100%;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
}
.mo-s-{{sceneId}} .mo-a-large {
  font-size: var(--mo-text-subtitle);
}
.mo-s-{{sceneId}} .mo-a-small {
  font-size: var(--mo-text-body);
}
@keyframes mo-s-{{sceneId}}-pulse {
  from {
    transform: scale(0.45);
    opacity: 0.9;
  }
  to {
    transform: scale(1.1);
    opacity: 0;
  }
}
@keyframes mo-s-{{sceneId}}-spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes mo-s-{{sceneId}}-bar {
  from {
    transform: scaleY(0.2);
  }
  to {
    transform: scaleY(1);
  }
}
